from typing import Any, Dict

from pydantic import BaseModel, Field


class OutboundCallResult(BaseModel):
    """Result returned by a call-time credential hook.

    Only ``metadata`` is merged onto the outbound wire today (MCP ``_meta`` or
    A2A ``Message.metadata``). Wrapping the wire payload in a typed envelope
    lets Rasa add optional, Rasa-owned fields later without changing the hook
    signatures.
    """

    metadata: Dict[str, Any] = Field(
        default_factory=dict,
        description="Key-value pairs merged into MCP _meta or A2A Message.metadata.",
    )
